 presentation048.onclick=async()=>{if(running)return;const buttons=[...panel.querySelectorAll('button')],first=results.length;buttons.forEach(b=>b.disabled=true);try{for(const action of actions048){await action();if(errors.length||results.slice(first).some(r=>r.result==='FAIL'))break;}}finally{buttons.forEach(b=>b.disabled=false);publish();}};


 // Yielding between batches keeps the browser and its automation channel usable.
 for(const button of panel.querySelectorAll('button')){const action=button.onclick;if(action)button.onclick=()=>setTimeout(()=>{Promise.resolve(action()).catch(e=>{errors.push(String(e));publish();});},75);}
 setInterval(()=>{if(running)publish();},3000);
